pub fn create(grid_size: Int) -> MultiScaleKAN {
  let micro = list.repeat(0.1, grid_size * grid_size)
  let meso = list.repeat(0.1, grid_size * 2)
  let macro = list.repeat(0.1, grid_size)

  MultiScaleKAN(
    micro_weights: micro,
    meso_weights: meso,
    macro_weights: macro,
    grid_size: grid_size,
  )
}

pub fn forward(model: MultiScaleKAN, input: List(Float)) -> List(Float) {
  let micro_out = apply_scale(input, model.micro_weights)
  let meso_out = apply_scale(micro_out, model.meso_weights)
  let macro_out = apply_scale(meso_out, model.macro_weights)

  macro_out
}

fn apply_scale(input: List(Float), weights: List(Float)) -> List(Float) {
  list.zip(input, weights)
  |> list.map(fn(pair) { pair.0 *. pair.1 })
}

pub fn update_weights(
  model: MultiScaleKAN,
  scale: Scale,
  new_weights: List(Float),
) -> MultiScaleKAN {
  case scale {
    Micro -> MultiScaleKAN(..model, micro_weights: new_weights)
    Meso -> MultiScaleKAN(..model, meso_weights: new_weights)
    Macro -> MultiScaleKAN(..model, macro_weights: new_weights)
  }
}

pub fn compute_gradients(
  model: MultiScaleKAN,
  input: List(Float),
  target: List(Float),
) -> MultiScaleKAN {
  let output = forward(model, input)
  let errors = list.zip(output, target)
    |> list.map(fn(pair) { pair.0 -. pair.1 })

  let micro_grad = compute_scale_gradient(errors, model.micro_weights)
  let meso_grad = compute_scale_gradient(errors, model.meso_weights)
  let macro_grad = compute_scale_gradient(errors, model.macro_weights)

  MultiScaleKAN(
    micro_weights: micro_grad,
    meso_weights: meso_grad,
    macro_weights: macro_grad,
    grid_size: model.grid_size,
  )
}

fn compute_scale_gradient(errors: List(Float), weights: List(Float)) -> List(Float) {
  list.zip(errors, weights)
  |> list.map(fn(pair) { pair.0 *. pair.1 *. 0.01 })
}
