    dict.insert(acc, node, 1.0)
  })

  TopologicalKAN(
    space: space,
    weights: weights,
    persistent_features: list.repeat(0.0, num_nodes),
  )
}

pub fn add_edge(model: TopologicalKAN, from: Int, to: Int) -> TopologicalKAN {
  let existing = dict.get(model.space.edges, from) |> result.unwrap([])
  let new_edges = dict.insert(model.space.edges, from, [to, ..existing])

  let new_space = TopologicalSpace(
    ..model.space,
    edges: new_edges,
  )

  TopologicalKAN(..model, space: new_space)
}

