  let generated = list.zip(network.meta_weights, pad_context(context, list.length(network.meta_weights)))
    |> list.map(fn(pair) { pair.0 *. pair.1 })

  HyperNetwork(..network, target_weights: generated)
}

fn pad_context(context: List(Float), target_length: Int) -> List(Float) {
  let current_length = list.length(context)
  case current_length < target_length {
    True -> list.append(context, list.repeat(0.0, target_length - current_length))
    False -> list.take(context, target_length)
  }
}

pub fn forward(network: HyperNetwork, input: List(Float)) -> List(Float) {
  let hidden = apply_layer(input, network.target_weights, network.hidden_dim)
  apply_activation(hidden)
}

