  list.range(0, output_size - 1)
  |> list.map(fn(i) {
    let start = i * list.length(input)
    let end = start + list.length(input)
    let row_weights = list.drop(weights, start) |> list.take(list.length(input))

    list.zip(input, row_weights)
    |> list.map(fn(pair) { pair.0 *. pair.1 })
    |> list.fold(0.0, float.add)
  })
}

fn apply_activation(values: List(Float)) -> List(Float) {
  list.map(values, fn(v) {
    case v >. 0.0 {
