pub type Multivector {
  Multivector(
    scalar: Float,
    vector: List(Float),
    bivector: List(Float),
    trivector: Float,
  )
}

pub fn create_multivector(dim: Int) -> Multivector {
  Multivector(
    scalar: 1.0,
    vector: list.repeat(0.0, dim),
    bivector: list.repeat(0.0, dim * {dim - 1} / 2),
    trivector: 0.0,
  )
}

pub fn geometric_product(a: Multivector, b: Multivector) -> Multivector {
  let new_scalar = a.scalar *. b.scalar

  let new_vector = list.zip(a.vector, b.vector)
    |> list.map(fn(pair) { pair.0 *. b.scalar +. pair.1 *. a.scalar })

  let new_bivector = list.zip(a.bivector, b.bivector)
    |> list.map(fn(pair) { pair.0 +. pair.1 })

  let new_trivector = a.trivector *. b.scalar +. b.trivector *. a.scalar

  Multivector(
    scalar: new_scalar,
    vector: new_vector,
    bivector: new_bivector,
    trivector: new_trivector,
  )
}

pub fn outer_product(a: Multivector, b: Multivector) -> Multivector {
  let bivector_from_vectors = compute_bivector(a.vector, b.vector)

  Multivector(
    scalar: 0.0,
    vector: list.repeat(0.0, list.length(a.vector)),
    bivector: bivector_from_vectors,
    trivector: 0.0,
  )
}

fn compute_bivector(v1: List(Float), v2: List(Float)) -> List(Float) {
  case v1, v2 {
    [a1, a2, ..], [b1, b2, ..] -> [a1 *. b2 -. a2 *. b1]
    _, _ -> []
  }
}

pub fn inner_product(a: Multivector, b: Multivector) -> Float {
  let vector_dot = list.zip(a.vector, b.vector)
    |> list.map(fn(pair) { pair.0 *. pair.1 })
    |> list.fold(0.0, float.add)

  a.scalar *. b.scalar +. vector_dot
}

pub fn embed_token(token_id: Int, dim: Int) -> Multivector {
  let vector = list.range(0, dim - 1)
    |> list.map(fn(i) { float.sin(int.to_float(token_id * i) /. 10000.0) })

  Multivector(
    scalar: 1.0,
    vector: vector,
    bivector: list.repeat(0.0, dim),
    trivector: 0.0,
  )
}

pub fn magnitude(mv: Multivector) -> Float {
  let vec_sum = list.map(mv.vector, fn(v) { v *. v })
    |> list.fold(0.0, float.add)

  let bivec_sum = list.map(mv.bivector, fn(v) { v *. v })
    |> list.fold(0.0, float.add)

  float.square_root(mv.scalar *. mv.scalar +. vec_sum +. bivec_sum +. mv.trivector *. mv.trivector)
}
