}

pub type Morphism {
  Morphism(
    source: Int,
    target: Int,
    transformation: fn(List(Float)) -> List(Float),
  )
}

pub type Category {
  Category(
    objects: Dict(Int, Object),
    morphisms: List(Morphism),
  )
}

pub type Functor {
  Functor(
    source_category: Category,
    target_category: Category,
    object_map: Dict(Int, Int),
    morphism_map: fn(Morphism) -> Morphism,
  )
}

pub fn create_category() -> Category {
  Category(
    objects: dict.new(),
    morphisms: [],
  )
}

pub fn add_object(cat: Category, obj: Object) -> Category {
  Category(
    ..cat,
    objects: dict.insert(cat.objects, obj.id, obj),
  )
}

pub fn add_morphism(cat: Category, morph: Morphism) -> Category {
  Category(
    ..cat,
    morphisms: [morph, ..cat.morphisms],
  )
}

pub fn compose_morphisms(f: Morphism, g: Morphism) -> Result(Morphism, Nil) {
  case f.target == g.source {
    True -> {
      let composed_fn = fn(x) { g.transformation(f.transformation(x)) }
      Ok(Morphism(
        source: f.source,
        target: g.target,
        transformation: composed_fn,
      ))
    }
    False -> Error(Nil)
  }
}

pub fn create_functor(
  source: Category,
  target: Category,
  obj_map: Dict(Int, Int),
) -> Functor {
  let morph_map = fn(m: Morphism) {
    let new_source = dict.get(obj_map, m.source) |> result.unwrap(m.source)
    let new_target = dict.get(obj_map, m.target) |> result.unwrap(m.target)

    Morphism(
      source: new_source,
      target: new_target,
      transformation: m.transformation,
    )
  }

  Functor(
    source_category: source,
    target_category: target,
    object_map: obj_map,
    morphism_map: morph_map,
  )
}

pub fn apply_functor(functor: Functor, obj_id: Int) -> Result(Int, Nil) {
  dict.get(functor.object_map, obj_id)
}

pub fn identity_morphism(obj_id: Int) -> Morphism {
  Morphism(
    source: obj_id,
    target: obj_id,
    transformation: fn(x) { x },
  )
}

pub fn natural_transformation(
  f: Functor,
  g: Functor,
  components: Dict(Int, fn(List(Float)) -> List(Float)),
) -> Dict(Int, fn(List(Float)) -> List(Float)) {
  components
