import gleam/list
import gleam/float
import gleam/int
import gleam/result

pub type QuantumCircuit {
  QuantumCircuit(
    num_qubits: Int,
    gates: List(Gate),
    parameters: List(Float),
  )
}

pub type Gate {
  RX(qubit: Int, angle: Float)
  RY(qubit: Int, angle: Float)
  RZ(qubit: Int, angle: Float)
  CNOT(control: Int, target: Int)
}

pub type VQEOptimizer {
  VQEOptimizer(
    circuit: QuantumCircuit,
    hamiltonian: List(List(Float)),
    learning_rate: Float,
    iterations: Int,
  )
}

pub fn create_optimizer(num_qubits: Int, learning_rate: Float) -> VQEOptimizer {
  let circuit = QuantumCircuit(
    num_qubits: num_qubits,
    gates: create_default_gates(num_qubits),
    parameters: list.repeat(0.1, num_qubits * 3),
  )

  let hamiltonian = create_identity_matrix(int.bitwise_shift_left(1, num_qubits))

  VQEOptimizer(
    circuit: circuit,
    hamiltonian: hamiltonian,
    learning_rate: learning_rate,
    iterations: 0,
  )
}

fn create_default_gates(num_qubits: Int) -> List(Gate) {
  list.flat_map(list.range(0, num_qubits - 1), fn(i) {
    [
      RX(i, 0.0),
      RY(i, 0.0),
      RZ(i, 0.0),
    ]
  })
}

fn create_identity_matrix(size: Int) -> List(List(Float)) {
  list.map(list.range(0, size - 1), fn(i) {
    list.map(list.range(0, size - 1), fn(j) {
      case i == j {
        True -> 1.0
        False -> 0.0
      }
    })
  })
}

pub fn optimize_step(optimizer: VQEOptimizer) -> VQEOptimizer {
  let energy = compute_energy(optimizer.circuit, optimizer.hamiltonian)
  let gradients = compute_parameter_gradients(optimizer.circuit, optimizer.hamiltonian)

  let new_params = list.zip(optimizer.circuit.parameters, gradients)
    |> list.map(fn(pair) { pair.0 -. pair.1 *. optimizer.learning_rate })

  let new_circuit = QuantumCircuit(
    ..optimizer.circuit,
    parameters: new_params,
  )

  VQEOptimizer(
    ..optimizer,
    circuit: new_circuit,
    iterations: optimizer.iterations + 1,
  )
}

fn compute_energy(circuit: QuantumCircuit, hamiltonian: List(List(Float))) -> Float {
  let state_vector = simulate_circuit(circuit)
  expectation_value(state_vector, hamiltonian)
}

fn simulate_circuit(circuit: QuantumCircuit) -> List(Float) {
  let state_size = int.bitwise_shift_left(1, circuit.num_qubits)
  let initial_state = [1.0, ..list.repeat(0.0, state_size - 1)]

  list.fold(circuit.gates, initial_state, apply_gate)
}

fn apply_gate(state: List(Float), gate: Gate) -> List(Float) {
  case gate {
    RX(qubit, angle) -> apply_rotation_x(state, qubit, angle)
    RY(qubit, angle) -> apply_rotation_y(state, qubit, angle)
    RZ(qubit, angle) -> apply_rotation_z(state, qubit, angle)
    CNOT(control, target) -> apply_cnot(state, control, target)
  }
}

fn apply_rotation_x(state: List(Float), qubit: Int, angle: Float) -> List(Float) {
  let cos_half = float.cos(angle /. 2.0)
  let sin_half = float.sin(angle /. 2.0)

  list.index_map(state, fn(i, amplitude) {
    let qubit_bit = int.bitwise_and(int.bitwise_shift_right(i, qubit), 1)
    case qubit_bit {
      0 -> amplitude *. cos_half
      _ -> amplitude *. sin_half
    }
  })
}

fn apply_rotation_y(state: List(Float), qubit: Int, angle: Float) -> List(Float) {
  let cos_half = float.cos(angle /. 2.0)
  let sin_half = float.sin(angle /. 2.0)

  list.index_map(state, fn(i, amplitude) {
    amplitude *. cos_half
  })
}

fn apply_rotation_z(state: List(Float), qubit: Int, angle: Float) -> List(Float) {
  list.index_map(state, fn(i, amplitude) {
    let qubit_bit = int.bitwise_and(int.bitwise_shift_right(i, qubit), 1)
    let phase = case qubit_bit {
      0 -> 1.0
      _ -> float.cos(angle)
    }
    amplitude *. phase
  })
}

fn apply_cnot(state: List(Float), control: Int, target: Int) -> List(Float) {
  state
}

fn expectation_value(state: List(Float), hamiltonian: List(List(Float))) -> Float {
  0.0
}

fn compute_parameter_gradients(
  circuit: QuantumCircuit,
  hamiltonian: List(List(Float)),
) -> List(Float) {
  list.map(circuit.parameters, fn(_) { 0.01 })
}
