pub fn create_accelerator(num_layers: Int, units_per_layer: Int) -> PhotonicAccelerator {
  let layers = list.map(list.range(0, num_layers - 1), fn(_) {
    create_photonic_layer(units_per_layer)
  })

  PhotonicAccelerator(
    layers: layers,
    input_modulators: list.repeat(0.0, units_per_layer),
    output_detectors: list.repeat(0.0, units_per_layer),
  )
}

fn create_photonic_layer(num_units: Int) -> PhotonicLayer {
  let mzi_units = list.map(list.range(0, num_units - 1), fn(_) {
    MZIUnit(
      phase_shifter_1: 0.0,
      phase_shifter_2: 0.0,
      splitting_ratio: 0.5,
    )
  })

  PhotonicLayer(
    mzi_units: mzi_units,
    wavelength: 1550.0,
    power_budget: 100.0,
  )
}

pub fn forward_pass(accelerator: PhotonicAccelerator, input: List(Float)) -> List(Float) {
  let modulated = modulate_input(input, accelerator.input_modulators)

  let propagated = list.fold(accelerator.layers, modulated, fn(signal, layer) {
    propagate_through_layer(signal, layer)
  })

  detect_output(propagated, accelerator.output_detectors)
}

fn modulate_input(input: List(Float), modulators: List(Float)) -> List(Float) {
  list.zip(input, modulators)
  |> list.map(fn(pair) { pair.0 *. float.cos(pair.1) })
}

fn propagate_through_layer(signal: List(Float), layer: PhotonicLayer) -> List(Float) {
  list.zip(signal, layer.mzi_units)
  |> list.map(fn(pair) {
    let input_power = pair.0
    let mzi = pair.1

    apply_mzi(input_power, mzi)
  })
}

fn apply_mzi(input_power: Float, mzi: MZIUnit) -> Float {
  let phase_1 = float.cos(mzi.phase_shifter_1)
  let phase_2 = float.cos(mzi.phase_shifter_2)

  let upper_arm = input_power *. mzi.splitting_ratio *. phase_1
  let lower_arm = input_power *. {1.0 -. mzi.splitting_ratio} *. phase_2

  upper_arm +. lower_arm
}

fn detect_output(signal: List(Float), detectors: List(Float)) -> List(Float) {
  list.zip(signal, detectors)
  |> list.map(fn(pair) {
    let optical_power = pair.0
    let detector_efficiency = pair.1

    optical_power *. optical_power *. {1.0 +. detector_efficiency}
  })
}

pub fn configure_mzi(
  accelerator: PhotonicAccelerator,
  layer_idx: Int,
  unit_idx: Int,
  phase_1: Float,
  phase_2: Float,
) -> PhotonicAccelerator {
  let updated_layers = list.index_map(accelerator.layers, fn(idx, layer) {
    case idx == layer_idx {
      True -> update_layer_mzi(layer, unit_idx, phase_1, phase_2)
      False -> layer
    }
  })

  PhotonicAccelerator(..accelerator, layers: updated_layers)
}

fn update_layer_mzi(
  layer: PhotonicLayer,
  unit_idx: Int,
  phase_1: Float,
  phase_2: Float,
) -> PhotonicLayer {
  let updated_mzis = list.index_map(layer.mzi_units, fn(idx, mzi) {
    case idx == unit_idx {
      True -> MZIUnit(..mzi, phase_shifter_1: phase_1, phase_shifter_2: phase_2)
      False -> mzi
    }
  })

  PhotonicLayer(..layer, mzi_units: updated_mzis)
}

pub fn compute_power_consumption(accelerator: PhotonicAccelerator) -> Float {
  list.fold(accelerator.layers, 0.0, fn(total, layer) {
    total +. layer.power_budget
  })
}
