import gleam/list
import gleam/dict.{type Dict}
import gleam/float
import gleam/int
import gleam/result

pub type Memory {
  Memory(
    cells: List(List(Float)),
    num_locations: Int,
    cell_size: Int,
  )
}

pub type ReadHead {
  ReadHead(
    weights: List(Float),
    read_vector: List(Float),
  )
}

pub type WriteHead {
  WriteHead(
    weights: List(Float),
    add_vector: List(Float),
    erase_vector: List(Float),
  )
}

pub type NTMController {
  NTMController(
    memory: Memory,
    read_heads: List(ReadHead),
    write_heads: List(WriteHead),
    controller_state: List(Float),
  )
}

pub fn create_ntm(
  num_locations: Int,
  cell_size: Int,
  num_read_heads: Int,
  num_write_heads: Int,
) -> NTMController {
  let memory = Memory(
    cells: list.repeat(list.repeat(0.0, cell_size), num_locations),
    num_locations: num_locations,
    cell_size: cell_size,
  )

  let read_heads = list.repeat(
    ReadHead(
      weights: list.repeat(1.0 /. int.to_float(num_locations), num_locations),
      read_vector: list.repeat(0.0, cell_size),
    ),
    num_read_heads,
  )

  let write_heads = list.repeat(
    WriteHead(
      weights: list.repeat(1.0 /. int.to_float(num_locations), num_locations),
      add_vector: list.repeat(0.0, cell_size),
      erase_vector: list.repeat(0.0, cell_size),
    ),
    num_write_heads,
  )

  NTMController(
    memory: memory,
    read_heads: read_heads,
    write_heads: write_heads,
    controller_state: list.repeat(0.0, 128),
  )
}

pub fn read_memory(ntm: NTMController, head_idx: Int) -> List(Float) {
  case list.at(ntm.read_heads, head_idx) {
    Ok(head) -> {
      list.fold(list.zip(ntm.memory.cells, head.weights), list.repeat(0.0, ntm.memory.cell_size), fn(acc, pair) {
        let cell = pair.0
        let weight = pair.1

        list.zip(acc, cell)
        |> list.map(fn(p) { p.0 +. p.1 *. weight })
      })
    }
    Error(_) -> list.repeat(0.0, ntm.memory.cell_size)
  }
}

pub fn write_memory(ntm: NTMController, head_idx: Int) -> NTMController {
  case list.at(ntm.write_heads, head_idx) {
    Ok(head) -> {
      let new_cells = list.zip(ntm.memory.cells, head.weights)
        |> list.map(fn(pair) {
          let cell = pair.0
          let weight = pair.1

          let erased = list.zip(cell, head.erase_vector)
            |> list.map(fn(p) { p.0 *. {1.0 -. p.1 *. weight} })

          list.zip(erased, head.add_vector)
          |> list.map(fn(p) { p.0 +. p.1 *. weight })
        })

      let new_memory = Memory(..ntm.memory, cells: new_cells)
      NTMController(..ntm, memory: new_memory)
    }
    Error(_) -> ntm
  }
}

pub fn content_addressing(
  memory: Memory,
  key: List(Float),
  beta: Float,
) -> List(Float) {
  let similarities = list.map(memory.cells, fn(cell) {
    cosine_similarity(key, cell)
  })

  softmax(list.map(similarities, fn(s) { s *. beta }))
}

fn cosine_similarity(a: List(Float), b: List(Float)) -> Float {
  let dot_product = list.zip(a, b)
    |> list.map(fn(pair) { pair.0 *. pair.1 })
    |> list.fold(0.0, float.add)

  let mag_a = float.square_root(
    list.map(a, fn(x) { x *. x })
    |> list.fold(0.0, float.add)
  )

  let mag_b = float.square_root(
    list.map(b, fn(x) { x *. x })
    |> list.fold(0.0, float.add)
  )

  case mag_a *. mag_b {
    0.0 -> 0.0
    denom -> dot_product /. denom
  }
}

fn softmax(values: List(Float)) -> List(Float) {
  let max_val = list.fold(values, 0.0, float.max)
  let exp_values = list.map(values, fn(v) { float.power(2.71828, v -. max_val) })
  let sum_exp = list.fold(exp_values, 0.0, float.add)

  list.map(exp_values, fn(e) { e /. sum_exp })
}

pub fn update_controller_state(
  ntm: NTMController,
  input: List(Float),
) -> NTMController {
  let read_vectors = list.index_map(ntm.read_heads, fn(idx, _) {
    read_memory(ntm, idx)
  })

  let combined_input = list.flatten([input, ..read_vectors])

  let new_state = list.zip(ntm.controller_state, pad_to_length(combined_input, list.length(ntm.controller_state)))
    |> list.map(fn(pair) { float.max(0.0, pair.0 +. pair.1 *. 0.1) })

  NTMController(..ntm, controller_state: new_state)
}

fn pad_to_length(lst: List(Float), target_len: Int) -> List(Float) {
  let current_len = list.length(lst)
  case current_len < target_len {
    True -> list.append(lst, list.repeat(0.0, target_len - current_len))
    False -> list.take(lst, target_len)
  }
}
